<?php
$token=is_string($_GET['token']??null)?$_GET['token']:'';$s=db()->prepare('SELECT * FROM orders WHERE access_token=?');$s->execute([$token]);$order=$s->fetch();if(!$order){http_response_code(404);require ROOT.'/pages/not-found.php';return;}$s=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$order['id']]);$items=$s->fetchAll();$statusNames=['pending'=>'À confirmer','confirmed'=>'Confirmée','packed'=>'Préparée','shipped'=>'Expédiée','delivered'=>'Livrée','cancelled'=>'Annulée'];
?><main id="main" class="content-page order-confirmation"><p class="eyebrow">VOTRE SÉLECTION EST ENREGISTRÉE</p><h1>Merci, <?=e($order['customer_name'])?>.</h1><p>Commande <?=e($order['reference'])?> · <?=e($statusNames[$order['status']]??$order['status'])?></p><p>Conservez le lien de cette page pour retrouver votre commande.</p><div class="cart-summary"><?php foreach($items as $item):?><div><span><?=e($item['product_name'])?> ×<?=$item['quantity']?><small><?=e($item['color_name'].' / '.$item['size_label'])?></small></span><strong><?=e(money((int)$item['unit_price_millimes']*(int)$item['quantity']))?></strong></div><?php endforeach;?><div><span>Livraison</span><strong><?=e(money((int)$order['shipping_millimes']))?></strong></div><div class="total"><span>Total à la livraison</span><strong><?=e(money((int)$order['total_millimes']))?></strong></div></div><a class="button-outline" href="<?=e(route('shop'))?>">Retour à la collection</a></main>